import flask
import binascii
import store

def create_app():
    app = flask.Flask(__name__)
    s = store.Store()

    def json_proof(p):
        res = {
            'siblings': [binascii.hexlify(s).decode('ascii') for s in p.siblings],
        }
        if p.key is not None:
            res['key'] = binascii.hexlify(p.key).decode('ascii')
            res['val'] = binascii.hexlify(p.val).decode('ascii')
        return flask.jsonify(res)

    @app.route("/<hexkey>", methods=["GET"])
    def lookup(hexkey):
        key = binascii.unhexlify(hexkey)
        return json_proof(s.lookup(key))

    @app.route("/<hexkey>", methods=["PUT"])
    def insert(hexkey):
        key = binascii.unhexlify(hexkey)
        val = flask.request.data
        return json_proof(s.insert(key, val))

    @app.route("/reset", methods=["POST"])
    def reset():
        s.reset()
        return ('', 204)

    return app

if __name__ == '__main__':
    app = create_app()
    app.run(debug=True, port=6160)

import argparse
import binascii
import client
import common
import requests

class RemoteStore:
    def __init__(self, url):
        self._url = url.encode('utf-8')

    def proof(self, response):
        j = response.json()
        k = j.get('key')
        v = j.get('val')
        if k is not None: k = binascii.unhexlify(k)
        if v is not None: v = binascii.unhexlify(v)
        p = common.Proof(k, v, [binascii.unhexlify(s) for s in j['siblings']])
        return p

    def lookup(self, key):
        response = requests.get(b'%s/%s' % (self._url, binascii.hexlify(key)))
        return self.proof(response)

    def insert(self, key, val):
        response = requests.put(b'%s/%s' % (self._url, binascii.hexlify(key)), data=val)
        return self.proof(response)

    def reset(self):
        requests.post(b'%s/reset' % self._url, b'')

