from common import H_empty, H_kv, H_internal, traversal_path, Proof

class Traversal:
    def __init__(self, path):
        self._siblings = []
        self._path = path
        self._cur_depth = 0

    def next_direction(self):
        """Return the next direction (left/right bit) and advance depth."""
        direction = bool(self._path[self._cur_depth])
        self._cur_depth += 1
        return direction

    def sibling(self, n):
        self._siblings.append(n)

    def get_siblings(self):
        return self._siblings

class Node:
    def __init__(self, hashval):
        self._hashval = hashval

    def hashval(self):
        return self._hashval

class EmptyNode(Node):
    def __init__(self):
        super().__init__(H_empty())

    def traverse(self, traversal):
        return traversal.leaf(self)

class KeyValueNode(Node):
    def __init__(self, key, val):
        self._key = key
        self._val = val
        h = H_kv(self._key, self._val)
        super().__init__(h)

    def key(self):
        return self._key

    def val(self):
        return self._val

    def traverse(self, traversal):
        return traversal.leaf(self)

class InternalNode(Node):
    def __init__(self, children):
        assert(len(children) == 2)
        self._children = children
        h = H_internal([c.hashval() for c in self._children])
        super().__init__(h)

    def traverse(self, traversal):
        """Traverse down the tree: record sibling, recurse into correct child."""
        idx = 1 if traversal.next_direction() else 0
        traversal.sibling(self._children[1 - idx])
        new_child = self._children[idx].traverse(traversal)
        children = list(self._children)
        children[idx] = new_child
        return InternalNode(children)

def node_proof(leaf, siblings):
    """Build a Proof from a leaf node and a list of sibling nodes."""
    if isinstance(leaf, EmptyNode):
        key = None
        val = None
    else:
        key = leaf.key()
        val = leaf.val()
    return Proof(key, val, [s.hashval() for s in siblings])

class LookupTraversal(Traversal):
    def __init__(self, key):
        super().__init__(traversal_path(key))
        self._leaf = None

    def leaf(self, n):
        """Record the leaf node reached during traversal."""
        self._leaf = n
        return n

    def proof(self):
        """Return the Proof for this lookup."""
        return node_proof(self._leaf, self.get_siblings())

class InsertTraversal(Traversal):
    def __init__(self, key, val):
        super().__init__(traversal_path(key))
        self._key = key
        self._val = val
        self._proof = None

    def leaf(self, n):
        """Handle reaching a leaf during insertion.

        If the leaf is empty or has the same key, replace it.
        If the leaf has a different key, create internal nodes to separate them.
        """
        self._proof = node_proof(n, self.get_siblings())

        if isinstance(n, EmptyNode):
            return KeyValueNode(self._key, self._val)

        if n.key() == self._key:
            return KeyValueNode(self._key, self._val)

        existing_path = traversal_path(n.key())
        split_depth = self._cur_depth
        while split_depth < len(self._path) and self._path[split_depth] == existing_path[split_depth]:
            split_depth += 1
        assert split_depth < len(self._path)

        new_leaf = KeyValueNode(self._key, self._val)
        if self._path[split_depth]:
            subtree = InternalNode([n, new_leaf])
        else:
            subtree = InternalNode([new_leaf, n])

        for depth in range(split_depth - 1, self._cur_depth - 1, -1):
            if self._path[depth]:
                subtree = InternalNode([EmptyNode(), subtree])
            else:
                subtree = InternalNode([subtree, EmptyNode()])

        return subtree

    def proof(self):
        return self._proof

class Store:
    def __init__(self):
        self.root = EmptyNode()

    def lookup(self, key):
        """Look up a key, returning a Proof."""
        traversal = LookupTraversal(key)
        self.root.traverse(traversal)
        return traversal.proof()

    def insert(self, key, val):
        """Insert a key-value pair, returning a Proof of the old state."""
        traversal = InsertTraversal(key, val)
        self.root = self.root.traverse(traversal)
        return traversal.proof()

    def reset(self):
        self.root = EmptyNode()

import hashlib
import bitstring

def H(*args):
    """SHA-256 hash of the concatenation of all arguments."""
    return hashlib.sha256(b"".join(args)).digest()

def H_empty():
    """Return the hash representing an empty node."""
    return b""

def H_kv(key, val):
    """Return the hash of a key-value pair."""
    return H(key, val)

def H_internal(children):
    """Return the hash of an internal node with two children hashes."""
    assert len(children) == 2
    return H(children[0], children[1])

def traversal_path(key):
    """Return the bitwise traversal path for a key (as a BitArray)."""
    return bitstring.BitArray(H(key))

class Proof:
    def __init__(self, key, val, siblings):
        self.key = key
        self.val = val
        self.siblings = siblings

class AttackOne:
    """Attack a Merkle tree client: forge a lookup proof for a fake key.

    The client has inserted (k, v). Given the store, return a different key
    that the client will accept via lookup (a collision or proof forgery).
    """
    def __init__(self, s):
