import struct

class BadEncodingException(Exception):
    pass

class UnsupportedValueException(Exception):
    pass

class encoder:
    def __init__(self):
        self.buf = bytearray()

    def encode_int(self, x):
        """Encode an integer using MessagePack format.

        Positive integers use fixint (0-127), uint8 (0xcc), uint16 (0xcd),
        uint32 (0xce), or uint64 (0xcf) formats.
        Negative integers use negative fixint (-32 to -1), int8 (0xd0),
        int16 (0xd1), int32 (0xd2), or int64 (0xd3) formats.
        """
        if 0 <= x <= 0x7f:
            self.buf.append(x)
        elif 0x80 <= x <= 0xff:
            self.buf.append(0xcc)
            self.buf.extend(struct.pack(">B", x))
        elif 0x100 <= x <= 0xffff:
            self.buf.append(0xcd)
            self.buf.extend(struct.pack(">H", x))
        elif 0x10000 <= x <= 0xffffffff:
            self.buf.append(0xce)
            self.buf.extend(struct.pack(">I", x))
        elif 0x100000000 <= x <= 0xffffffffffffffff:
            self.buf.append(0xcf)
            self.buf.extend(struct.pack(">Q", x))
        elif -32 <= x < 0:
            self.buf.append(x & 0xff)
        elif -0x80 <= x < -32:
            self.buf.append(0xd0)
            self.buf.extend(struct.pack(">b", x))
        elif -0x8000 <= x < -0x80:
            self.buf.append(0xd1)
            self.buf.extend(struct.pack(">h", x))
        elif -0x80000000 <= x < -0x8000:
            self.buf.append(0xd2)
            self.buf.extend(struct.pack(">i", x))
        elif -(1 << 63) <= x < -0x80000000:
            self.buf.append(0xd3)
            self.buf.extend(struct.pack(">q", x))
        else:
            raise UnsupportedValueException(x)

    def encode_bool(self, x):
        """Encode a boolean: True -> 0xc2, False -> 0xc3."""
        self.buf.append(0xc3 if x else 0xc2)

    def encode_str(self, x):
        """Encode a string using fixstr (0xa0+n), str8 (0xda), str16 (0xd9),
        or str32 (0xdb) format, following MessagePack encoding."""
        data = x.encode("utf-8")
        n = len(data)
        if n <= 0x1f:
            self.buf.append(0xa0 | n)
        elif n <= 0xff:
            self.buf.append(0xd9)
            self.buf.extend(struct.pack(">B", n))
        elif n <= 0xffff:
            self.buf.append(0xda)
            self.buf.extend(struct.pack(">H", n))
        elif n <= 0xffffffff:
            self.buf.append(0xdb)
            self.buf.extend(struct.pack(">I", n))
        else:
            raise UnsupportedValueException(x)
        self.buf.extend(data)

    def encode_bytes(self, x):
        """Encode raw bytes using bin8 (0xc4), bin16 (0xc5), or bin32 (0xc6) format."""
        n = len(x)
        if n <= 0xff:
            self.buf.append(0xc4)
            self.buf.extend(struct.pack(">B", n))
        elif n <= 0xffff:
            self.buf.append(0xc5)
            self.buf.extend(struct.pack(">H", n))
        elif n <= 0xffffffff:
            self.buf.append(0xc6)
            self.buf.extend(struct.pack(">I", n))
        else:
            raise UnsupportedValueException(x)
        self.buf.extend(x)

    def encode_dict(self, x):
        """Encode a dict using fixmap (0x80+n), map16 (0xde), or map32 (0xdf) format."""
        n = len(x)
        if n <= 0x0f:
            self.buf.append(0x80 | n)
        elif n <= 0xffff:
            self.buf.append(0xde)
            self.buf.extend(struct.pack(">H", n))
        elif n <= 0xffffffff:
            self.buf.append(0xdf)
            self.buf.extend(struct.pack(">I", n))
        else:
            raise UnsupportedValueException(x)
        for k, v in x.items():
            self.encode(k)
            self.encode(v)

    def encode_none(self, x):
        self.buf.append(0xc0)

    def encode_array(self, x):
        """Encode a list/tuple using fixarray (0x90+n), array16 (0xdc),
        or array32 (0xdd) format."""
        n = len(x)
        if n <= 0x0f:
            self.buf.append(0x90 | n)
        elif n <= 0xffff:
            self.buf.append(0xdc)
            self.buf.extend(struct.pack(">H", n))
        elif n <= 0xffffffff:
            self.buf.append(0xdd)
            self.buf.extend(struct.pack(">I", n))
        else:
            raise UnsupportedValueException(x)
        for v in x:
            self.encode(v)

    def encode(self, x):
        """Encode a Python value into MessagePack format.

        Dispatches to type-specific encode methods based on the value's type.
        Supported types: None, str, bytes, list/tuple, dict, bool, int.
        """
        if x is None:
            self.encode_none(x)
        elif type(x) == bool:
            self.encode_bool(x)
        elif type(x) == int:
            self.encode_int(x)
        elif type(x) == str:
            self.encode_str(x)
        elif type(x) == bytes:
            self.encode_bytes(x)
        elif isinstance(x, (list, tuple)):
            self.encode_array(x)
        elif isinstance(x, dict):
            self.encode_dict(x)
        else:
            raise UnsupportedValueException(x)

    def get_buf(self):
        return bytes(self.buf)

class decoder:
    def __init__(self, data):
        self.buf = data

    def get(self, n):
        if len(self.buf) < n:
            raise BadEncodingException('not enough data: need', n)
        d = self.buf[:n]
        self.buf = self.buf[n:]
        return d

    def unpack(self, fmt):
        n = struct.calcsize(fmt)
        return struct.unpack(fmt, self.get(n))

    def unpack_one(self, fmt):
        return self.unpack(fmt)[0]

    def decode_uint(self, b, fmt):
        return self.unpack_one(fmt)

    def decode_int(self, b, fmt):
        return self.unpack_one(fmt)

    def decode_bool(self, b):
        """Decode a boolean: 0xc2 -> True, 0xc3 -> False."""
        if b == 0xc2:
            return False
        if b == 0xc3:
            return True
        raise BadEncodingException('invalid bool encoding', b)

    def decode_str(self, b):
        """Decode a MessagePack string from the buffer.

        Handles fixstr (0xa0-0xbe), str8 (0xda), str16 (0xd9), str32 (0xdb).
        Returns the decoded UTF-8 string.
        """
        if 0xa0 <= b <= 0xbf:
            n = b & 0x1f
        elif b == 0xd9:
            n = self.unpack_one(">B")
        elif b == 0xda:
            n = self.unpack_one(">H")
        elif b == 0xdb:
            n = self.unpack_one(">I")
        else:
            raise BadEncodingException('invalid string encoding', b)
        return self.get(n).decode("utf-8")

    def decode_bytes(self, b):
        """Decode raw bytes from the buffer.

        Handles bin8 (0xc4), bin16 (0xc5), bin32 (0xc6).
        """
        if b == 0xc4:
            n = self.unpack_one(">B")
        elif b == 0xc5:
            n = self.unpack_one(">H")
        elif b == 0xc6:
            n = self.unpack_one(">I")
        else:
            raise BadEncodingException('invalid bytes encoding', b)
        return self.get(n)

    def decode_dict(self, b):
        """Decode a MessagePack map from the buffer.

        Handles fixmap (0x80-0x8e), map16 (0xde), map32 (0xdf).
        Returns a Python dict.
        """
        if 0x80 <= b <= 0x8f:
            n = b & 0x0f
        elif b == 0xde:
            n = self.unpack_one(">H")
        elif b == 0xdf:
            n = self.unpack_one(">I")
        else:
            raise BadEncodingException('invalid dict encoding', b)
        out = {}
        for _ in range(n):
            key = self.decode()
            val = self.decode()
            out[key] = val
        return out

    def decode_nil(self, b):
        return None

    def decode_array(self, b):
        """Decode a MessagePack array from the buffer.

        Handles fixarray (0x90-0x9e), array16 (0xdc), array32 (0xdd).
        Returns a tuple.
        """
        if 0x90 <= b <= 0x9f:
            n = b & 0x0f
        elif b == 0xdc:
            n = self.unpack_one(">H")
        elif b == 0xdd:
            n = self.unpack_one(">I")
        else:
            raise BadEncodingException('invalid array encoding', b)
        return tuple(self.decode() for _ in range(n))

    def decode_fixint(self, b):
        """Decode a fixint: 0x00-0x7f as positive, 0xe0-0xff as negative."""
        if 0x00 <= b <= 0x7f:
            return b
        if 0xe0 <= b <= 0xff:
            return b - 0x100
        raise BadEncodingException('invalid fixint encoding', b)

    def decode(self):
        """Read the next value from the buffer by dispatching on the type byte."""
        b = self.unpack_one(">B")
        if b <= 0x7f or b >= 0xe0:
            return self.decode_fixint(b)
        if b == 0xc0:
            return self.decode_nil(b)
        if b == 0xc2 or b == 0xc3:
            return self.decode_bool(b)
        if b == 0xc4 or b == 0xc5 or b == 0xc6:
            return self.decode_bytes(b)
        if 0x80 <= b <= 0x8f or b == 0xde or b == 0xdf:
            return self.decode_dict(b)
        if b == 0xcc:
            return self.decode_uint(b, ">B")
        if b == 0xcd:
            return self.decode_uint(b, ">H")
        if b == 0xce:
            return self.decode_uint(b, ">I")
        if b == 0xcf:
            return self.decode_uint(b, ">Q")
        if b == 0xd0:
            return self.decode_int(b, ">b")
        if b == 0xd1:
            return self.decode_int(b, ">h")
        if b == 0xd2:
            return self.decode_int(b, ">i")
        if b == 0xd3:
            return self.decode_int(b, ">q")
        if (0xa0 <= b <= 0xbf) or b == 0xd9 or b == 0xda or b == 0xdb:
            return self.decode_str(b)
        if (0x90 <= b <= 0x9f) or b == 0xdc or b == 0xdd:
            return self.decode_array(b)
        raise BadEncodingException('unsupported type byte', b)

