class Client:
    def __init__(self, store, root_hash = H_empty()):
        self._store = store
        self._root_hash = root_hash
        self.verbose_validate = False

    def validate(self, path_key, proof):
        """Validate a proof against the client's root hash.

        Recompute the root hash from the proof's leaf and siblings
        using the traversal path, and verify it matches self._root_hash.
        Raises Exception("Root hash mismatch") if invalid.
        """
        assert(type(proof) == Proof)
        assert(proof.key == None or type(proof.key) == bytes)
        assert(proof.val == None or type(proof.val) == bytes)
        assert(type(proof.siblings) == list and all([type(s) == bytes for s in proof.siblings]))

        if proof.key is None:
            cur = H_empty()
        else:
            cur = H_kv(proof.key, proof.val)

        path = traversal_path(path_key)
        for depth, sibling in reversed(list(enumerate(proof.siblings))):
            if path[depth]:
                cur = H_internal([sibling, cur])
            else:
                cur = H_internal([cur, sibling])

        if self.verbose_validate:
            print("validate", path_key, proof.key, len(proof.siblings), cur)

        if cur != self._root_hash:
            raise Exception("Root hash mismatch")

    def lookup(self, key):
        """Look up a key through the store, validate the proof, return the value or None."""
        proof = self._store.lookup(key)
        self.validate(key, proof)
        if proof.key != key:
            return None
        return proof.val

    def insert(self, key, val):
        """Insert a key-value pair, validate the proof, and update root hash."""
        proof = self._store.insert(key, val)
        self.validate(key, proof)

        cur = H_kv(key, val)
        path = traversal_path(key)

        if proof.key not in (None, key):
            other_path = traversal_path(proof.key)
            split_depth = len(proof.siblings)
            while split_depth < len(path) and path[split_depth] == other_path[split_depth]:
                split_depth += 1
            assert split_depth < len(path)

            other = H_kv(proof.key, proof.val)
            if path[split_depth]:
                cur = H_internal([other, cur])
            else:
                cur = H_internal([cur, other])

            for depth in range(split_depth - 1, len(proof.siblings) - 1, -1):
                if path[depth]:
                    cur = H_internal([H_empty(), cur])
                else:
                    cur = H_internal([cur, H_empty()])

        for depth, sibling in reversed(list(enumerate(proof.siblings))):
            if path[depth]:
                cur = H_internal([sibling, cur])
            else:
                cur = H_internal([cur, sibling])

        self._root_hash = cur

    def reset(self):
        self._store.reset()
        self._root_hash = H_empty()

from common import H_empty, H_kv, H_internal, traversal_path, Proof

class Traversal:
    def __init__(self, path):
        self._siblings = []
        self._path = path
        self._cur_depth = 0

    def next_direction(self):
        """Return the next direction (left/right bit) and advance depth."""
        direction = bool(self._path[self._cur_depth])
        self._cur_depth += 1
        return direction

    def sibling(self, n):
        self._siblings.append(n)

    def get_siblings(self):
        return self._siblings

class Node:
    def __init__(self, hashval):
        self._hashval = hashval

    def hashval(self):
        return self._hashval

class EmptyNode(Node):
    def __init__(self):
        super().__init__(H_empty())

    def traverse(self, traversal):
        return traversal.leaf(self)

class KeyValueNode(Node):
    def __init__(self, key, val):
        self._key = key
        self._val = val
        h = H_kv(self._key, self._val)
        super().__init__(h)

    def key(self):
        return self._key

    def val(self):
        return self._val

    def traverse(self, traversal):
        return traversal.leaf(self)

class InternalNode(Node):
    def __init__(self, children):
        assert(len(children) == 2)
        self._children = children
        h = H_internal([c.hashval() for c in self._children])
        super().__init__(h)

    def traverse(self, traversal):
        """Traverse down the tree: record sibling, recurse into correct child."""
        idx = 1 if traversal.next_direction() else 0
        traversal.sibling(self._children[1 - idx])
        new_child = self._children[idx].traverse(traversal)
        children = list(self._children)
        children[idx] = new_child
        return InternalNode(children)

def node_proof(leaf, siblings):
    """Build a Proof from a leaf node and a list of sibling nodes."""
    if isinstance(leaf, EmptyNode):
        key = None
        val = None
    else:
        key = leaf.key()
        val = leaf.val()
    return Proof(key, val, [s.hashval() for s in siblings])

class LookupTraversal(Traversal):
    def __init__(self, key):
        super().__init__(traversal_path(key))
        self._leaf = None

    def leaf(self, n):
        """Record the leaf node reached during traversal."""
        self._leaf = n
        return n

    def proof(self):
        """Return the Proof for this lookup."""
        return node_proof(self._leaf, self.get_siblings())

class InsertTraversal(Traversal):
    def __init__(self, key, val):
        super().__init__(traversal_path(key))
        self._key = key
        self._val = val
        self._proof = None

    def leaf(self, n):
        """Handle reaching a leaf during insertion.

        If the leaf is empty or has the same key, replace it.
        If the leaf has a different key, create internal nodes to separate them.
        """
        self._proof = node_proof(n, self.get_siblings())

        if isinstance(n, EmptyNode):
            return KeyValueNode(self._key, self._val)

        if n.key() == self._key:
            return KeyValueNode(self._key, self._val)

        existing_path = traversal_path(n.key())
        split_depth = self._cur_depth
        while split_depth < len(self._path) and self._path[split_depth] == existing_path[split_depth]:
            split_depth += 1
        assert split_depth < len(self._path)

        new_leaf = KeyValueNode(self._key, self._val)
        if self._path[split_depth]:
            subtree = InternalNode([n, new_leaf])
        else:
            subtree = InternalNode([new_leaf, n])

        for depth in range(split_depth - 1, self._cur_depth - 1, -1):
            if self._path[depth]:
                subtree = InternalNode([EmptyNode(), subtree])
            else:
                subtree = InternalNode([subtree, EmptyNode()])

        return subtree

    def proof(self):
        return self._proof

class Store:
    def __init__(self):
        self.root = EmptyNode()

    def lookup(self, key):
        """Look up a key, returning a Proof."""
        traversal = LookupTraversal(key)
        self.root.traverse(traversal)
        return traversal.proof()

    def insert(self, key, val):
        """Insert a key-value pair, returning a Proof of the old state."""
        traversal = InsertTraversal(key, val)
        self.root = self.root.traverse(traversal)
        return traversal.proof()

    def reset(self):
        self.root = EmptyNode()
